t.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    },\n    {\n      \"id\": \"sae-qualification-record\",\n      \"method\": \"sae\",\n      \"title\": \"Record reviewed SAE qualification\",\n      \"engineCLI\": \"steerlab-server sae qualification record --help\",\n      \"mac\": \"Research methods: Author request, review inputs, then open execution and evidence. Both CLIs use science interview/draft/publish and the same managed engine.\",\n      \"http\": \"POST /api/science/plan; POST /api/science/submit\",\n      \"compute\": \"cpu\",\n      \"outputs\": [\n        \"Diagnostic path and per-layer stability summary\"\n      ],\n      \"restriction\": \"Explicit config, reviewed input hashes and a fresh engine plan are required. GPU work requires immutable model revisions. Outputs are new records; local/Slurm execution uses the existing scientific owner. Native MLX numerical equivalence is not claimed. Remote training and analysis outputs are retained; the diagnostic cleanup policy does not authorize their removal.\",\n      \"actions\": [\n        {\n          \"id\": \"post-science-plan\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/plan\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Inspect staged scientific inputs and execution resources without execution or authorship.\"\n        },\n        {\n          \"id\": \"post-science-submit\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/submit\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Execute a reviewed scientific operation and retain its scientific output type.\"\n        }\n      ],\n      \"access\": {\n        \"status\": \"http\",\n        \"client\": \"runner science-call <operation> --action <action-id> --request <request.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    },\n    {\n      \"id\": \"sae-qualification-show\",\n      \"method\": \"sae\",\n      \"title\": \"Inspect an SAE qualification record\",\n      \"engineCLI\": \"steerlab-server sae qualification show <path> --json\",\n      \"mac\": \"Research methods: Inspect or pin SAE roster; Show qualification record. Both clients: science sae-show.\",\n      \"http\": \"POST /api/science/workspace/{action}\",\n      \"compute\": \"cpu\",\n      \"outputs\": [\n        \"See the selected operation public response and immutable artifact records.\"\n      ],\n      \"restriction\": \"Read-only inspection of existing recorded qualification. No status is inferred beyond the record.\",\n      \"actions\": [\n        {\n          \"id\": \"post-science-workspace\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/workspace/{action}\",\n          \"serviceRole\": \"workbench\",\n          \"authorityReason\": \"Author and publish local scientific requests, review and pin SAE rosters, or verify/import local custody; runner staging remains isolated execution.\"\n        }\n      ],\n      \"access\": {\n        \"status\": \"http\",\n        \"client\": \"runner science-call <operation> --action <action-id> --request <request.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    },\n    {\n      \"id\": \"jlens-fit\",\n      \"method\": \"jlens\",\n      \"title\": \"Fit a J-lens\",\n      \"engineCLI\": null,\n      \"mac\": \"Research methods: Author request, review inputs, then open execution and evidence. Both CLIs use science interview/draft/publish and the same managed engine.\",\n      \"http\": \"POST /api/science/plan; POST /api/science/submit\",\n      \"compute\": \"gpu\",\n      \"outputs\": [\n        \"Immutable fitting run, float32 Jacobians, fitting report, checkpoint, and a ready-to-import artifact description.\"\n      ],\n      \"restriction\": \"Fits with the pinned reference Jacobian estimator on a prepared, unquantized checkpoint. Start with a small timing pilot. Automatic scheduler resume is disabled; an explicit checkpoint continues in a new reviewed run. Export/fetch/import returns completed runs; artifact-plan/import then registers the lens. Partial checkpoint recovery uses permitted file transfer. Fitting is not qualification or behavioral evidence.\",\n      \"actions\": [\n        {\n          \"id\": \"post-science-plan\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/plan\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Inspect staged scientific inputs and execution resources without execution or authorship.\"\n        },\n        {\n          \"id\": \"post-science-submit\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/submit\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Execute a reviewed scientific operation and retain its scientific output type.\"\n        }\n      ],\n      \"access\": {\n        \"status\": \"http\",\n        \"client\": \"runner science-call <operation> --action <action-id> --request <request.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    },\n    {\n      \"id\": \"jlens-fit-benchmark\",\n      \"method\": \"jlens\",\n      \"title\": \"Benchmark J-lens fitting\",\n      \"engineCLI\": null,\n      \"mac\": \"Research methods: Author request, review inputs, then open execution and evidence. Both CLIs use science interview/draft/publish and the same managed engine.\",\n      \"http\": \"POST /api/science/plan; POST /api/science/submit\",\n      \"compute\": \"gpu\",\n      \"outputs\": [\n        \"Timing, memory, per-prompt Jacobian agreement, and averaged-lens agreement for a small, fixed corpus.\"\n      ],\n      \"restriction\": \"Runs sequential isolated cases; no model downloads or environment installation. A passed tolerance is not runtime qualification or scientific validation.\",\n      \"actions\": [\n        {\n          \"id\": \"post-science-plan\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/plan\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Inspect staged scientific inputs and execution resources without execution or authorship.\"\n        },\n        {\n          \"id\": \"post-science-submit\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/submit\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Execute a reviewed scientific operation and retain its scientific output type.\"\n        }\n      ],\n      \"access\": {\n        \"status\": \"http\",\n        \"client\": \"runner science-call <operation> --action <action-id> --request <request.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    },\n    {\n      \"id\": \"jlens-fit-round\",\n      \"method\": \"jlens\",\n      \"title\": \"Plan a fixed-budget fitting round\",\n      \"engineCLI\": null,\n      \"mac\": \"Research methods: Author request, review inputs, then open execution and evidence. Both CLIs use science interview/draft/publish and the same managed engine.\",\n      \"http\": \"POST /api/science/plan; POST /api/science/submit; POST /api/science/fitting-round/{job_id}/{action}\",\n      \"compute\": \"cpu\",\n      \"outputs\": [\n        \"Divide one global row budget into disjoint fitting requests, then review and top up the queue. Materialization starts no GPU work.\"\n      ],\n      \"restriction\": \"Uses reviewed inputs and immutable scientific outputs. No environment installation, automatic retries, or scientific qualification.\",\n      \"actions\": [\n        {\n          \"id\": \"post-science-plan\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/plan\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Inspect staged scientific inputs and execution resources without execution or authorship.\"\n        },\n        {\n          \"id\": \"post-science-submit\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/submit\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Execute a reviewed scientific operation and retain its scientific output type.\"\n        },\n        {\n          \"id\": \"post-fitting-round\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/fitting-round/{job_id}/{action}\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Review and coordinate disjoint fitting shards and a deterministic merge using durable scientific jobs.\"\n        }\n      ],\n      \"access\": {\n        \"status\": \"http\",\n        \"client\": \"runner science-call <operation> --action <action-id> --request <request.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    },\n    {\n      \"id\": \"jlens-fit-merge\",\n      \"method\": \"jlens\",\n      \"title\": \"Merge completed fitting shards\",\n      \"engineCLI\": null,\n      \"mac\": \"Research methods: Author request, review inputs, then open execution and evidence. Both CLIs use science interview/draft/publish and the same managed engine.\",\n      \"http\": \"POST /api/science/plan; POST /api/science/submit\",\n      \"compute\": \"cpu\",\n      \"outputs\": [\n        \"Merge raw float32 sums in deterministic global-row order, weighted by fitted rows, with overlap detection and recorded source lineage.\"\n      ],\n      \"restriction\": \"Uses reviewed inputs and immutable scientific outputs. No environment installation, automatic retries, or scientific qualification.\",\n      \"actions\": [\n        {\n          \"id\": \"post-science-plan\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/plan\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Inspect staged scientific inputs and execution resources without execution or authorship.\"\n        },\n        {\n          \"id\": \"post-science-submit\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/submit\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Execute a reviewed scientific operation and retain its scientific output type.\"\n        }\n      ],\n      \"access\": {\n        \"status\": \"http\",\n        \"client\": \"runner science-call <operation> --action <action-id> --request <request.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    },\n    {\n      \"id\": \"jlens-fit-assess\",\n      \"method\": \"jlens\",\n      \"title\": \"Assess successive lenses on held-out text\",\n      \"engineCLI\": null,\n      \"mac\": \"Research methods: Author request, review inputs, then open execution and evidence. Both CLIs use science interview/draft/publish and the same managed engine.\",\n      \"http\": \"POST /api/science/plan; POST /api/science/submit\",\n      \"compute\": \"gpu\",\n      \"outputs\": [\n        \"Measure agreement between two lenses and with the model’s actual final residual on declared held-out token positions.\"\n      ],\n      \"restriction\": \"Uses reviewed inputs and immutable scientific outputs. No environment installation, automatic retries, or scientific qualification.\",\n      \"actions\": [\n        {\n          \"id\": \"post-science-plan\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/plan\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Inspect staged scientific inputs and execution resources without execution or authorship.\"\n        },\n        {\n          \"id\": \"post-science-submit\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/submit\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Execute a reviewed scientific operation and retain its scientific output type.\"\n        }\n      ],\n      \"access\": {\n        \"status\": \"http\",\n        \"client\": \"runner science-call <operation> --action <action-id> --request <request.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    }\n  ]\n}\n",
      "extraction.md": "# Choose and extract a steering direction\n\nCompare declared activation populations before testing an intervention.\n\nChoose the contrast with the researcher. Record the construct, counter-construct or reference population, model revision, rendering, reading position and intended claim before generating data.\n\n| Method declaration | Inputs | Meaning and limitation |\n|---|---|---|\n| meanDifference | prompts/concepts/<concept>/positive.jsonl and negative.jsonl; each line has a text string | Difference of class means. Equal counts are not required by the arithmetic. Match nuisance features such as topic and register. |\n| lat | The same files, aligned row by row with equal lengths | Paired-difference PCA with normalization and alternating orientation. Order is part of this implementation's recipe. RepE-inspired, not an unchanged RepE replication. |\n| emotionGrandMean | prompts/emotions/<concept>/stories.jsonl for every named corpus member; text rows | Concept mean minus the pooled corpus mean, including the target. Corpus membership defines the comparison. |\n| designatedReference | Target and explicitly chosen reference stories.jsonl files | Difference from that reference population. Do not select a reference merely because a file exists. |\n\nA minimal stimulus row is {\"text\":\"A statement expressing the declared position.\"}. It is a schema example, not a validated stimulus set. Keep extraction stimuli, held-out probes, development tasks and final evaluation tasks separate. A neutral corpus used to denominate norm-unit alpha is another pinned input, not the negative class.\n\nUse `authoring prompt contrastive-pairs --concept <concept> --positive <definition> --negative <definition>` for paired stimuli. For story and neutral corpora, hand the coworker the text-row schema and author instructions in this guide; the prompt emitter has no dedicated kind for those corpora. Hand the resulting prompt to a coworker; independently review topic, length, register, polarity leakage, duplication and split overlap before importing. Do not treat generated data as validated evidence.\n\nDeclare with experiment attach --method and the explicit rendering/reading/reference/corpus flags shown by that client's help. Authoring is local; execution is steerlab-cli experiment extract on supported Mac cells or steerlab-server experiment extract on the Python engine. Use the client bundle workflow for supported remote stages. A template-aware reading position under raw rendering refuses; assistant-voice extraction is Python-only.\n\nInspect recipe and input pins in the vector sidecar. Then use held-out validation, a development sweep, baseline and declared controls before freezing final measurement. Cosine alignment or a stable vector alone does not establish a construct or a causal behavioral effect.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n",
      "finetuning.md": "# Prepare and compare fine-tuned adapters\n\nSeparate training-recipe choices from subsequent study claims.\n\nChoose the training objective, supervised output, dataset splits, base model/revision, target modules, scaling, seed, checkpoint-selection rule and comparison intervention with the researcher.\n\nUse the LoRA row schemas and coworker brief below, then `steerlab-server data check lora <package-manifest-or-dir> --json`. There is no LoRA kind in the generic prompt emitter. Use the workbench finetune plan operation before train or submit; the Python engine CLI also has finetune plan/train/submit. The existing Adapters pane reaches these owners. A plan is not training success, and a scheduler receipt is not a completed adapter.\n\nKeep labels, masks and split roles explicit. Compare training recipes on objective/masking, effective adapter scaling, optimization schedule, target layers, precision and checkpoint selection; shared rank or a similarly named alpha does not make two recipes matched. Preserve dataset hashes and the resolved model revision in the training artifact.\n\nInspect the produced adapter and its qualification/evaluation evidence before composing an agent. Attach the reviewed agent to an ordinary comparison study with baseline and held-out prompts. A fine-tuning improvement on its training objective is not evidence that a steering vector and adapter implement the same intervention.\n\n## Dataset rows and training declaration\n\nEvidence-grade document mode has one complete example per row:\n\n```json\n{\"id\":\"document-1\",\"text\":\"One independently sourced training document.\"}\n```\n\nInstruction-chat mode uses user/assistant text and optional system text:\n\n```json\n{\"id\":\"instruction-1\",\"system\":\"Follow the declared task.\",\"user\":\"A training input.\",\"assistant\":\"The approved target response.\"}\n```\n\nThe loader also accepts `prompt`/`completion` aliases; normalized rows use `user`/`assistant`. Unknown row keys refuse. Do not combine examples into a token stream or silently truncate them. Declare the long-document split/refuse policy. Keep training and validation files independently authored; retain a separate final evaluation corpus.\n\nThe package manifest names each arm's `adapter`, `training` and `validation` references with actual `path`/`sha256` values and the package QC report. Run the data check before authoring a training configuration. Select `document` or `instruction_chat`, base model/revision, dataset pins and evidence-grade policy explicitly in the fine-tuning plan; the workbench exposes its current request schema at `/openapi.json`. The engine CLI takes `finetune plan --config <file> --json` before `train` or `submit` with that reviewed config. An exploratory inline recipe is not interchangeable with the pinned dataset recipe.\n\nAsk the coworker to return the chosen row format, independent splits and an audit of source permissions, duplication, label correctness and systematic nuisance differences. Ask the reviewer to compare intended supervised tokens with the selected engine recipe before approving a causal comparison.\n\n## Engine config spelling\n\nThe engine CLI config is **snake_case**, unlike the workbench HTTP body's camelCase wire. Use `base_model_id`, `revision`, `training_mode`, `train_paths`, `validation_paths`, `expected_hashes` (path to actual SHA-256), `dataset_root`, `dataset_manifest_path`, `dataset_manifest_hash`, `dataset_bundle_id`, `reserved_evaluation_hashes` and `evidence_grade`. Training choices include `rank`, `alpha`, `dropout`, `learning_rate`, `target_modules`, `dtype`, `seed`, `epochs`/`max_steps`, `batch_size`, `gradient_accumulation`, `warmup_steps`, `lr_schedule`, `max_grad_norm`, `weight_decay`, `max_sequence_tokens`, `long_document_policy`, `chunk_overlap_tokens`, `eval_interval_steps`, `checkpoint_interval_steps`, `selection_metric` and `control_arm`. Unknown fields refuse. Do not paste HTTP camelCase directly into the engine config.\n\nThe plan validates this declaration and reports the dataset, schedule and evidence refusals before training. Ask about substantive unset choices; a library default is not researcher approval. Keep the complete reviewed plan beside the proposed config in the handoff.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n",
      "jlens.md": "# Acquire and qualify a J-lens\n\nInspect a lens under its model, layer and token constraints.\n\nAsk which model/revision, fitted lens, source/target layers and token-level question the researcher wants to inspect. Distinguish acquisition, arithmetic qualification, predictive readout and behavioral evidence.\n\nUse the J-lens pane or the existing jlens family and /api/jlens routes for acquisition/import, token options, direction derivation, qualification, G0, probing, report and support. Read each operation's public help or request schema. Qualification fixtures belong to the instrument; do not replace them with study-specific examples to obtain a pass.\n\nPreserve lens identity, model revision, tokenizer conventions and supported fitted layers. Imported or acquired files are not qualified solely because they load. Unknown applicability requires qualification or an explicit unsupported result.\n\nOutputs include lens metadata, qualification records and readout reports. A token ranking is a model-dependent readout; it does not by itself show that a concept caused a behavioral change. Use a separately designed steering intervention and held-out outcome measurement for that claim.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n\n## Import a custom fitted lens\n\nUse an artifact you already have. Place this description beside its tensor file;\nreplace the miniature example geometry with the actual fitted model and tensors.\nA coding agent should read the supplied source documentation and ask about missing\nmetadata, never infer a model revision or layer mapping from a filename.\n\n```json\n{\n  \"schemaVersion\": 1,\n  \"kind\": \"jlens\",\n  \"modelID\": \"example/model\",\n  \"modelRevision\": null,\n  \"hiddenSize\": 2,\n  \"layerCount\": 4,\n  \"tensorFile\": \"lens.safetensors\",\n  \"lens\": {\n    \"tier\": \"testing\",\n    \"targetLayer\": 3,\n    \"layers\": {\"0\": \"layer_0\", \"2\": \"layer_2\"},\n    \"promptsFitted\": 100,\n    \"corpus\": \"Description of the actual fitting corpus\",\n    \"maxSeqLen\": 128\n  }\n}\n```\n\nThis example declares two fitted 2×2 matrices; it does not invent the missing\nlayer 1. It supports readouts at those fitted layers; the current steering-token\nvector builder needs every source layer before the final block. Transport is\n`J_l @ h` to the final block before normalization. Optional\n`configFile` retains original source configuration bytes. Optional `source` can\nrecord a repository, its exact revision, and/or a URL; unknown values are omitted.\nKnown fit-time `modelRevision` is a 40-character commit; unknown remains null.\nSafetensors and numeric NPZ are portable; tensor-only PyTorch checkpoints and\nBF16 need the optional PyTorch reader. A saved JacobianLens `J` mapping is read as\n`layer_<number>` keys, with checkpoint geometry checked against the description.\n\nBoth clients offer `science artifact-plan <description.json> --json`, then\n`science artifact-import <description.json> --plan-sha256 <reviewed-hash> --json`.\nSelect the destination workspace with the client's usual root/workspace option.\nThe app's J-lens dialog offers **Import my own lens files** and explicitly stages\nfiles to the connected Python workbench before review. Import publishes a fresh\nlens ID, retains source copies, and does not qualify it or train anything. Use\nthat explicit lens ID when several fits exist for the same model.\n\nChoose intended use with the researcher: optional `lens.tier` is `testing`\n(the default, for rehearsal) or `evidence` (intended study use). This declaration\napplies to every custom lens, including models in the published catalog. It is\nnot a claim of validity or a passing qualification. Freezing a study with this\nreadout still needs qualification bound to the exact lens bytes, runtime, and\nlayers, plus the study's normal pins. To change intended use, update the source\ndescription, review a fresh plan, and import a new lens; keep existing artifacts\nunchanged. Published-source imports retain their existing tier policy.\n\n## Fit a new lens from your own text\n\nThe managed operation is `jlens-fit`. In the app's J-lens dialog choose\n**Fit a new lens…**, or open its interview under Research methods. Both clients\nexpose `science interview jlens-fit --json`, then the usual\n`science draft`/`publish` and execution/collection workflow. The engine uses\nthe same owner through `POST /api/science/plan` and `/api/science/submit`.\nUse an installed engine with the pinned optional `jlens` extra. Authoring is\navailable without GPU packages; fitting loads only an already-prepared model.\n\nSupply a UTF-8 JSONL corpus with exactly `id` and `text` per row:\n\n```json\n{\"id\":\"passage-1\",\"text\":\"Replace this example with a sufficiently long passage from your documented text source.\"}\n```\n\nUse text representative of the population where you will use the lens. This is\nnot paired positive/negative concept data. Preserve source and licensing details\nin the authoring notes. Keep separate text for assessing readouts; fitting\nconvergence is not held-out validity. The default considers the first four rows\nas a timing pilot. Increase the limit after inspecting cost and coverage.\nThere is no hidden shuffle or chat template. Tokenization uses the checkpoint's\nnative special-token settings; the reference position mask omits the first\n16 positions and the final token. Short rows are explicitly recorded as skipped.\n\nConfiguration fields: `modelID`, immutable 40-hex `revision`, `corpus`\n(`{path,sha256}`), optional `sourceLayers` (blank/null means every source\nlayer), `maxPrompts` (4), `maxSeqLen` (128), `skipFirst` (16),\n`dimBatch` (1), `checkpointEvery` (4), `dtype` (bfloat16),\n`device` (cuda), `tier` (testing), and optional `checkpoint`\n(`{path,sha256}` naming state.json beside sums.safetensors).\n\nThe estimator sums output cotangents over valid target positions, averages\ngradients over valid source positions, and averages the resulting matrices over\nusable prompts. The final target is the last residual block before normalization.\nSource layers are explicit; a partial lens can support readouts, while the current\ntoken-vector builder needs every source layer. Weights never change. Accumulation\nand final lens storage use float32 even when model execution uses bfloat16.\n\nCost includes one replicated forward and roughly hidden-size/dimBatch backward\npasses per usable passage. More dimensions per pass need more activation memory.\nA successful inference run does not prove that a hybrid attention implementation\nsupports this backward calculation. Measure a pilot on the actual checkpoint,\nengine, and hardware before scheduling a large fit. Runtime or numerical errors\nare reported; they are not silently counted as short corpus rows.\n\nFor a worked example (not a specification for your selected model), width 5,376\nand 61 source layers require 5,376 backward passes per usable row at dimension\nbatch 1. Each float32 matrix set occupies 6.57 GiB; sums and the current row's\nmatrices alone need 13.14 GiB of CPU memory. Each checkpoint writes about\n6.57 GiB, and model weights, activations, temporary matrices, and serialization\nneed additional space. Batch 8 processes eight dimensions together in 672\npasses, using more activation memory; it does not promise eightfold acceleration.\nEven four rows can be an expensive pilot. Measure before increasing the limit.\nThe shared request review estimates these costs from the exact model's cached\nconfiguration when available, without loading or downloading weights. Otherwise\nit reports unknown geometry and asks for review on the prepared engine. These\nare arithmetic estimates, not measured peak memory or elapsed time.\n\nCompleted fits return an immutable run with fit-report.json,\njacobians.safetensors, artifact-description.json, captured input text, and a\ncheckpoint. Use normal science export/fetch/import and verify custody to bring\nthe run home. Then review artifact-description.json with artifact-plan and use\nartifact-import to register this particular fit in the lens library. In the app,\nuse **Import my own lens files…** on that returned description. Fitting precision,\nmodel revision, corpus hash, and original report survive registration. Qualify\nthat registered lens for its intended runtime separately; fitting is not\nqualification and supplies no claim about causal behavioral meaning.\n\nPeriodic checkpoint snapshots live in the run's named\n`.steerlab/jlens-fitting-state/` scratch directory. Each snapshot is published\ncoherently before this invocation prunes its prior scratch snapshot. Completed\nruns retain an immutable final checkpoint and the source checkpoint metadata/hashes;\nprivate working copies are then removed. Cancellation retains the last completed\nscratch snapshot. Wait for the original job to stop, use the site's permitted\ntransfer tools to recover state.json and sums.safetensors together if needed,\nand select state.json in a new request. The corpus, model, numerical runtime\nsettings, dependency versions, and estimator must match under the versioned\nfitting compatibility contract. Source hashes remain recorded as provenance, so\na documentation-only change does not prevent continuation. A narrowly identified\ncheckpoint from the original fitting release is recognized under the same\ncontract; unknown older formats require review. Numerical changes require a new\ncontract or an explicitly assessed migration, not silently ignoring differences.\nThe row limit may increase; progress is never appended to the old run. Review\nand execution independently read and verify checkpoint tensors, with a status\nmessage before hashing. Multi-gigabyte files can take several minutes on slow\nstorage; do not interpret that alone as a hang.\nThe managed scheduler still reports automatic resume as unavailable: checkpoint\ncontinuation is a new, explicit reviewed job. Failed jobs are not evidence exports.\nNo general cleanup of fitting runs or recovered checkpoints is authorized.\nFailed runs accumulate intentionally. Ordinary errors after run creation,\nincluding model loading and checkpoint restoration, leave a failure record with\nthe stage, reason, and recovery references when storage permits. An abrupt kill\nor full disk can prevent that record; the run has no completion marker, and its\nlast completed scratch checkpoint remains the recovery point.\n\n### Corpus-authoring prompt to copy\n\nHelp me choose or prepare a fitting corpus for a J-lens on my selected model.\nFirst ask what text population the lens should represent and whether I want to\nuse existing files, author the text myself, or delegate data creation. Do not\ngenerate passages or launch agents without my agreement. If authoring is agreed,\nreturn UTF-8 JSONL with unique id and nonempty text fields only, with enough\ntokens after the chosen truncation and skipped-position settings. Keep source\nand licensing notes separately. Propose held-out passages separately for later\nreadout assessment. Explain that this corpus fits an averaged instrument and\ndoes not establish a behavioral concept. Do not invent model commits, execute\nfitting, or download weights.\n\n## Preparing an existing fitting corpus\n\nThe app's Fit a new lens → Data → Prepare corpus flow and both clients expose\n`science corpus-preview <spec.json>` and `science corpus-publish <previewID>\n--plan-sha256 <planSHA256> --destination prompts/fitting/<new-name> --json`.\nUse `--root <workspace>` on command lines. The workbench API equivalents are\n`POST /api/science/workspace/corpus-preview` with `workspaceRoot` and `specText`,\nand `corpus-publish` with `workspaceRoot`, `previewID`, `planSHA256`, and\n`destination`. All call one portable preparation owner.\n\nA minimal local specification is\n`{\"source\":{\"kind\":\"local\",\"files\":[\"sources/text.jsonl\"]},\"count\":1000,\"seed\":0}`.\nSources may be text, JSONL, CSV, or Parquet files already in the workspace; the\napp can copy selected local originals there. Public dataset sources use\n`{\"kind\":\"huggingface\",\"dataset\":\"owner/dataset\",\"revision\":\"main\",\"files\":[\"train/*.parquet\"]}`.\nChoose actual repository paths for the intended configuration and split;\npreview resolves and records the exact dataset commit. It can download those\npublic files, never model weights or dataset scripts. Gated sources need a\nlocal export. Selected files are bounded to 2 GiB, and output to 64 MiB.\n\nOptional fields: `textColumn` (default `text`), `documentColumn` (default null),\n`selection` (`seeded` or `first`), `seed` (default 0), `count` (default 1000),\n`minChars` (default 1), `passageChars` (0 keeps records), and `scanLimit` (default\n100000). Sampling covers only scanned records; inspect the actual counts and\nwarnings. `first` with minimum 600 characters preserves the reference-style\nlong-record selection policy; seeded sampling is a different policy. A passage\nis one seeded character window, not sentence segmentation. An optional\n`tokenizer` object (`modelID`, exact `revision`, `maxSeqLen`, `skipFirst`) previews\nlengths with a locally cached tokenizer; absence is guidance, not a data refusal.\n\nPreview captures candidate bytes in `.steerlab/corpus-preparations/` and shows\nexamples. Publication verifies those bytes, creates a fresh directory, and\nreturns `fittingInputs.corpus` and `fittingInputs.corpusReceipt`. Use both in the\nfit config; the receipt records sources, sampling, selected records, and token\nreview, and is captured in the fitting run. Existing manually authored corpora\ncan omit it. Prepare assessment text separately, preferably from another source\nsplit; this action does not establish document-level independence.\n\nAsk the researcher about the text population and sampling choices in plain\nlanguage. Do not infer permission to download, generate, or delegate dataset\ncreation from a model or concept choice. Preparation does not start fitting.\n\n## Pilot measurements and reliable remote collection\n\nA new fit writes `row-resources.jsonl` beside `progress.jsonl`. It records each\nreference-kernel call's dimension batch, elapsed seconds, tokens, and available\nCUDA memory measurements. `fit-report.json` includes per-layer finiteness,\nallocated and reserved device peaks, process-lifetime peak host RSS, compilation\nstatus, optional kernel package versions, and observations from executed\nattention modules. An installed package is not proof its fast kernel executed;\nunknown dispatch is reported as unverified. Non-CUDA device measurements are\nunavailable rather than zero. A failure report names the phase, batch, latest\ncompleted checkpoint, and available memory, including failures before backward.\nThese measurements describe this runtime and corpus; they do not establish\nreadout quality or predict proportional speedups from larger batches.\n\nAfter packaging inputs, transfer the archive beneath the runner's configured\nrun root using the site's permitted transport. `runner science-stage` (Mac:\n`remote science-stage`) receives that server path and the archive SHA-256. Both\nclients save `.steerlab/diagnostic-requests/<digest>.json` in the local workspace\nand return its absolute `localRequestPath`. Pass that file as the request\nargument of `science-plan`, then of `science-submit` with the reviewed plan hash,\non the same controller. Both verbs re-verify the staged files, so a request that\ncarries a multi-gigabyte checkpoint can take minutes before either answers; both\nclients allow an hour for these calls. The app carries this staged request automatically. An API\ncaller uses the `request` object returned by `POST /api/science/stage` directly.\nDo not send the original published request to a runner that cannot see the\nlocal workspace: its file references describe authoring inputs, not staged\nexecution copies.\n\nStaging and export may hash or compress gigabytes before sending response bytes.\nBoth clients allow an hour for these requests; the Python client's explicit\nrequest timeout overrides that default. `science-fetch` streams the archive,\nchecks its digest, and imports it through the existing custody owner. The\ncomplete archive still includes the final checkpoint. No checkpoint is dropped\nsilently, and a verified transfer is not scientific qualification.\n\nFor older deployments or site-required direct transfer, have the controller\nfinish the idempotent export through its `/api/science/jobs/<job-id>/export`\nendpoint with a suitably long client timeout. Obtain the returned `bundlePath`\nand `bundleSha256`, transfer that **complete diagnostic evidence archive** using\nthe permitted transport, then run locally:\n\n```sh\nsteerlab science import <local-evidence.tar.gz> --sha256 <bundleSha256> --root <workspace> --json\nsteerlab science verify-custody <receiptSHA256> --root <workspace> --json\n```\n\nThe Mac equivalents use `steerlab-cli science`. A directory copied by rsync or\nan ordinary tar archive is not this evidence format. If export is still running,\nwait and request its reference again; do not resubmit the fit. Keep remote\noriginals until local custody verifies. Register the collected lens through\n`science artifact-plan` and `science artifact-import`; qualification and held-out\nassessment remain separate decisions.\n\nA code push does not restart an existing controller. `cluster status` reports\nrunning and deployed build identities when the controller supports those fields;\nolder controllers report them as unknown. Arrange a reviewed restart after\nchecking active work, then make fresh execution plans. Do not treat a successful\npush as proof the running controller loaded the new code.\n\nOn filesystems without native create-only rename, an interrupted publication can\nleave an empty directory claim. This is incomplete output. Confirm that no\npublisher is live before removing only that empty directory by hand and retrying;\notherwise choose a new destination. Never delete populated output as a repair.\n\n\n## From a pilot to a measured fitting round\n\nAsk first what readout the researcher needs, which text should represent it, and\nwhat compute budget they approve. Explain that a **fitting round** divides one\nfixed total of corpus rows among independent jobs; merging combines their\ncontributions. More rows or a stable running average alone do not establish\nthat a lens answers the research question. Keep the declared held-out text\nseparate, and compare the readouts and the research conclusions.\n\nFour managed operations are available from **Research methods → Author request**\nin the app, `science interview/draft/publish` in either client, and the workbench\n`/api/science/workspace/{action}` routes. Execution uses the usual package,\nstage, plan, submit, inspect, fetch, and custody flow on either client or the\nHTTP API. A runner executes; it does not author the researcher's workspace.\n\n| Operation | Researcher choice | Result |\n| --- | --- | --- |\n| `jlens-fit-benchmark` | A published fresh fitting request of at most eight rows, dimension batches (baseline 1), kernel policy, compilation comparison, and numerical tolerances | Per-prompt gradient and mean-lens agreement, throughput, and memory, with failures visible |\n| `jlens-fit-round` | A published fixed-budget fit, shard count, first global corpus row, partition layout, and concurrency cap | Immutable shard requests and a round plan; materializing this plan starts no GPU fitting |\n| `jlens-fit-merge` | Completed disjoint fit directories, and whether missing planned rows are acceptable | A weighted merged lens, checkpoint, and explicit coverage/lineage report |\n| `jlens-fit-assess` | Two registered lens IDs, pinned held-out text, layers, and token-position budget | Per-layer readout agreement and comparisons with the final residual; no automatic qualification |\n\n### Measure speed and numerical agreement together\n\nUse the same small corpus and exact checkpoint for each benchmark case. Choose\nbatches such as `1, 8, 16`; larger batches may exhaust memory. `kernelPolicies`\ncan be `current`, `torch`, or `torch,current`. The explicit Torch policy uses\ninspectable model-owned fallbacks; if the installed model has no such fallback,\nuse the current policy and request a tested model adapter. `compareCompiled`\nadds compiled cases. The first case is the comparison baseline. Each case runs\nin a fresh subprocess, so a failed CUDA context does not contaminate the next.\nThe report records the GPU name, compute capability, capacity, and CUDA build\nwhen available; each subprocess has separate compiler caches. It compares every fitted prompt's matrices and the final mean, not\nonly a final score. Tolerances remain visible researcher choices.\n\nTiming excludes model loading, includes first-call compilation and temporary\nmatrix writes, and applies only to the measured rows and environment. Temporary\nmatrices retain the baseline and current case until comparison, then are\nremoved; allow disk space for both sets of per-row matrices. A killed worker\ncan leave scratch under `.steerlab/jlens-benchmark-state/`. A benchmark report\ncontains measurements, not an importable lens. Failed cases remain in the\nreport; a `COMPLETED` report is not a claim that every case passed.\n\nA successful report can be selected as the optional **Measured pilot report**\n(`benchmarkReport`) in a later fit. The review shows its matching case's rows\nper hour and an extrapolation at the requested row cap, with runtime and\nlimitations. This is not a scheduler walltime guarantee. The default dimension\nbatch remains 1. No benchmark changes defaults or approves a continuation\nacross a numerical-runtime mismatch. Kernel policy, compilation, optional\npackage versions, Torch, and Transformers stay bound in checkpoint identity.\n\nOptional Linux kernel candidates are available in the explicit\n`Server[jlens-kernels]` extra. This is separate from normal setup and from the\npinned `jlens` reference extra. It is **not a resolved CUDA environment lock or a\nqualified configuration**. After the researcher approves an environment change,\nthe running agent should first obtain a `pip install --dry-run --report ...`\nplan in the intended environment, review dependencies and build prerequisites,\nand then install that reviewed selection. Installing `jlens-kernels` neither\nacquires weights nor imports lenses. Do not run `bootstrap --with-jlens` merely\nto add kernels: that existing option also acquires the curated lenses. Never\nchange a running job's environment. Compare fallback and accelerated gradients\nand lenses before interpreting a speedup; package presence alone does not prove\nwhich kernel ran. Qualification remains a separate instrument check.\n\n### Review and execute a fixed-budget round\n\nThe base fitting request's `maxPrompts` is the **global row budget**, including\nshort rows later skipped. `startRow` is zero-based in the same pinned corpus.\nInterleaved partitions distribute successive rows across shards; contiguous\npartitions give each shard a consecutive block. The plan lists every global\nrow and the per-shard count, and shows minimum retained lens/checkpoint storage\nwhen model dimensions are cached. Budget also for staging, exports, and\nrecovered checkpoints. This is not a peak-memory estimate.\n\nAfter materialization, use its durable job ID in the app's **Scientific inputs,\nevidence and cleanup → J-lens fitting rounds** controls. Review the shard queue,\nconfirm the displayed plan, and top it up. Review again as capacity becomes\nfree. The cap counts active scientific jobs on this controller; it does not\nreplace the site's scheduler policy or account for unrelated controllers.\nUncertain submissions reserve capacity and are not retried. Inspect durable\njobs and scheduler state before reconciling uncertainty; never resubmit merely\nbecause a request timed out. Cancellation requests must be followed by a job\nstatus check. There is no automatic background refill.\n\nBoth command lines can invoke these same controls with `science-call`:\n\n```sh\nsteerlab runner science-call jlens-fit-round --action post-fitting-round --request round-action.json --runner <url> --json\nsteerlab-cli remote science-call jlens-fit-round --action post-fitting-round --request round-action.json --site <id> --json\n```\n\nFor review, `round-action.json` is:\n\n```json\n{\"path\":{\"job_id\":\"<materialized-round-job-id>\",\"action\":\"plan\"},\"query\":{},\"body\":{}}\n```\n\nThe HTTP equivalent is `POST /api/science/fitting-round/<job-id>/plan` with `{}`.\n`status` and `merge-plan` also take an empty body. `submit`, `cancel`, and\n`merge-submit` require `{\"planSHA256\":\"<fresh-plan-hash>\",\"confirmAction\":true}`.\nUse the hash from `plan` for submission/cancellation and the hash from\n`merge-plan` for merging. Mutations recheck inputs and capacity. The round's\nshard requests automatically use its verified execution capsule; do not hand\nedit their paths. Plan and submit allow time for multi-gigabyte verification.\n\nQueue reviews identify the active scientific jobs occupying this controller's\ncapacity, including jobs from other rounds or methods. Uncertain shard indices\nare listed separately and reserve slots until reconciled. The Mac shows this\nexplanation beside the queue controls; API and CLI results carry the same\n`capacity` summary, job IDs, statuses, and round membership. A round with pending\nshards and no available slots may simply be waiting for another scientific job.\nInspect those jobs and wait for capacity; do not resubmit an uncertain shard.\n\nEach shard can be continued from its own checkpoint using ordinary `jlens-fit`\ncontinuation and its original row selection. A continuation is a new run. The\nround helper merges its original completed child jobs; for continued shards,\nauthor `jlens-fit-merge` explicitly with each shard's **latest** completed run.\nNever include both a shard and its continuation or an earlier merge covering\nthe same rows. The owner checks global coverage under the same pinned corpus\nand numerical identity and refuses overlaps, including ancestor contributions.\n\nMerge uses raw float32 sums weighted by fitted-row counts, excluding skipped\nrows. It records accumulation order (ascending first global row, then checkpoint\nhash), missing rows, and source hashes. Grouped float32 addition can differ\nfrom serial addition; compare within declared tolerances. A partial merge stays\nlabelled partial. Collect and verify its evidence, then register its\n`artifact-description.json` with the usual artifact-plan/import workflow.\nBefore adding any contribution, merge requires its raw sums divided by its\nfitted-row count to equal its published mean exactly. This checks that the\ncheckpoint and lens are a matching completed output, without a tolerance that\ncould hide a changed source. A mismatch names the run and layer. Select matching\noutput; never repair this by editing completed runs. A future change to stored\nprecision or division semantics needs an explicit format migration. Merge runs\nas a CPU child within the controller's allocation: its accumulator remains in\nhost memory, while source sums and means are read one layer at a time.\nRegistration now carries the fit report hash, reference commit, kernel hash,\nand driver hash when the verified source report supplies them. Third-party\nartifacts with unknown provenance remain unknown.\n\n### Define stopping and assess readouts\n\nOptional `stopping` on a serial fit has the shape\n`{\"threshold\":0.002,\"window\":10,\"minPrompts\":100}`. Those values are an example,\nnot defaults or a promise that 100 rows suffice. The statistic is the maximum\nover source layers of the relative Frobenius change of the running mean.\nStopping requires N consecutive valid values strictly below the threshold,\nafter the minimum number of **successfully fitted** rows. Skipped rows do not\nadvance the window. A zero-norm previous layer mean makes the statistic\nunavailable, clears the window, and continues to the row budget; it never\ncounts as convergence. The window travels in checkpoint state. Reports name\nwhether stability or the row budget ended the fit. Fixed-budget shards refuse\nper-shard stopping: independent stopping changes the sample and does not\nreconstruct the serial convergence series.\n\nFor `jlens-fit-assess`, choose two registered versions and held-out text. On the\nsame captured source activations, the owner applies each J matrix, then the\nmodel's actual final normalization and unembedding. It reports Jensen–Shannon\ndivergence in nats and top-k token-set overlap, both between lenses and against\nthe actual final residual. Aggregation weights assessed token positions equally;\nonly the first eligible positions up to the declared cap are assessed. Position\nand layer choices are recorded. These are distributional readout comparisons,\nnot causal interventions. A matching fitting-corpus hash is flagged; a different\nhash does not establish independence. Neither metric automatically qualifies a\nlens or decides whether the research conclusions are stable.\n\nAssessment forwards each usable row once and saves only the selected source\nand final-layer activations, preserving their dtype and token order. Temporary\nfiles live under `.steerlab/jlens-assessment-state/` in the execution root. It\nthen compares all rows one source layer at a time: each of the two lens matrices\nis read and placed on the model device once per layer, with at most one layer\npair resident. It does not cache two complete lenses in host or GPU memory.\nEight-position readout chunks and per-layer accumulation order are unchanged.\n\nThe input review (app, CLIs, and API) reports a temporary activation tensor-byte\nupper bound, the selected activation bytes per row, and the float32 lens-pair\nsize. These are **not peak-memory estimates**: allow for model weights, forward\nactivations, vocabulary logits, transfers, allocator overhead, and file headers.\nThe report adds actual staged tensor bytes and row counts, plus lens-layer read\nand placement counts. CPU copies still occur on a CPU runner; these counts are\nnot measurements of physical GPU transfers. Temporary activations are removed\non success and ordinary exceptions. A killed process or machine restart can\nleave scratch files; no automatic recovery or managed cleanup is claimed.\nThe completed report remains under `runs/`. Large-model throughput and peak\nmemory still require measurement on the intended execution hardware.\n\nThe corpus, checkpoints, and completed runs remain immutable. Hash reuse is\nlimited to unchanged regular files within one bounded input-review operation;\na new request and the queued worker verify afresh. It does not eliminate every\nplan, submit, and worker read. No general fitting-run or checkpoint cleanup has\nbeen added. Keep original remote evidence until verified local custody, and\nfollow the site's storage policy through an explicitly reviewed cleanup.\n",
      "jspace.md": "# Inspect an intervention in J-space\n\nSeparate arithmetic fidelity, readout predictiveness and causal evidence.\n\nUse this exploratory analysis when the researcher wants to inspect the lens readout of a vector's downstream residual change. It does not train an intervention or replace a behavioral study.\n\nRun steerlab-server optvec jspace --config <file>. Required config fields are vectorArtifacts (extension-less artifact paths), lensID and probeItems:{path,sha256}. The probes are pinned choice-row JSONL. Optional observationLayers must be fitted source layers at or above the injection layer. Other supported keys include alphaMultiple, nullSeed, nullDraws, seed, topK, microbatchSize, modelID, revision, device, dtype, promptMode, systemPrompt, qwenThinkingEnabled and name. Unknown keys refuse.\n\nAsk the researcher to choose the vector, lens, probes, observation layers and dose. Obtain hashes from inspected bytes, never fabricate them. alphaMultiple scales the artifact's own norm; it is not the ordinary residual-norm alpha. The seed field is inert here because no generation sampling occurs; nullSeed governs matched-norm random draws.\n\nReport arithmetic fidelity and precision-floor flags separately from predictive readout. Null draws are comparators, not a calibrated test. Behavioral/causal evidence is absent from this operation; collect it through a separate controlled run. The engine CLI is the supported execution path; the app guide exposes that restriction explicitly.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n\n## Shared method authoring and managed execution\n\nUse `science interview <operation> --json` to read the exact form fields used by the app. Answer the purpose, proposed claim, controls and selection questions; supply field values as strings (including integer seeds) and put reviewed extra engine settings in `advanced`. `science draft <operation> --answers <answers.json> --json` resolves file hashes and reports all captured inputs without execution. `science publish <operation> --answers <answers.json> --destination requests/<new-name> --plan-sha256 <reviewed-hash> --json` publishes the machine request and rationale together, refusing changed inputs or an existing destination. Both commands are available under each client executable.\n\nUse the resulting request file with `science input-plan` and `science package`, transfer and stage through the declared site policy, then review and submit the engine plan. The shared form is an authoring aid; the engine still checks its complete scientific config before execution. A successful parser or custody check is not scientific qualification. The workbench API exposes the same local owner at `POST /api/science/workspace/{action}`; it takes `workspaceRoot`, `operation`, and for draft/publish `answersText` (the exact JSON text). Publish also requires `destination` and `planSHA256`. Runner services cannot author the local workspace.\n\nJ-space is an analysis method, not an OptVec training procedure. Its public managed operation is `jspace`. The historical engine command `optvec jspace` currently accepts OptVec artifacts because it reads their stored layer and absolute dose; that implementation restriction is not a claim that J-space depends scientifically on optimization. Other intervention artifact types require a separate admission change.\n",
      "judging.md": "# Complete deferred judgments\n\nMaintain blinding, packet identity and the declared judge panel.\n\nDecide the rubric, judge panel, evaluation sample and intended reliability claim before scoring. Use independent judgments rather than asking a coding agent to invent favorable labels.\n\nInspect experiment sweep/evaluate awaiting through the existing workbench/runner endpoints. Hand each coworker the pinned blinded packets and their instructions, not an unblinded arm map. Require the operation's exact judgment row schema, packet IDs, judge identities and instruction pins; never fabricate missing judgments or edit packet files to make coverage pass.\n\nComplete through the existing sweep/evaluate complete-judgment routes or `steerlab-server experiment complete-sweep-judgment` (sweep) and `steerlab-server experiment complete-judgment` (evaluate). Both take `<study> --awaiting-run <run> --judgments <file> --json`. These owners verify coverage, packet hashes and epoch. A sweep completion can append the selected recommendation to a draft; evaluate completion aggregates judgment evidence. Preserve that distinction and the owners' lifecycle gates.\n\nOutputs are judgment records, agreement/report data and, where applicable, the recommendation. Judge agreement alone does not establish validity. Missing/partial coverage, stale packets or a changed study must produce the owner's repair, not an automatic retry with new pins.\n\n## Intake shape and blinding\n\nFetch `GET /api/experiment/{name}/sweep/awaiting` or `GET /api/experiment/{name}/evaluate/awaiting` on the selected engine. An example row shape is:\n\n```json\n{\"packetID\":\"issued-packet-id\",\"judge\":\"declared-judge-id\",\"winner\":\"A\",\"model\":\"declared-judge-model\"}\n```\n\nIDs/model strings above are placeholders for the issued packet and pinned judge, never new identities. Winner is `A`, `B` or `tie`. CLI input accepts a JSON list, a `{\"judgments\":[...]}` object, or JSONL. HTTP bodies name `sweepRun` or `evaluateRun` plus `judgments`. Evaluation accepts the optional `instructionsSha256` claim; its owner records mismatches as warnings, not a hard gate. Sweep has no such claim field; its CLI refuses one rather than dropping it.\n\nSupply the full packet × judge coverage required by the issued manifest, including the actual model/annotator declarations it requests. A coder should prepare delivery and check completeness without seeing the unblinding map; independent judging coworkers see only the assigned blinded packets and pinned instructions. Completion is idempotent: an existing result can be returned, and a sweep may heal a missing draft recommendation projection. It does not rewrite its source evidence.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n",
      "multi-agent.md": "# Design a multi-agent study\n\nDeclare interaction structure and controls before casting agents.\n\nAsk about roles, shared materials, private information, turn order, visibility/routing, stopping rules and measured outcomes. Specify baseline, each-solo and combined-treatment comparisons where they answer the question; do not assume a composition sweep is the research design.\n\nUse authoring study multiAgent for the shared interview and study-pack skeleton. Semantic panel JSON describes roles, materials, turns, routing, contracts and outcomes. Model settings and agent artifacts belong in the study's casting. Task prompts do not substitute for a panel transcript.\n\nPublish with panel import after checking source bytes. Inspect the panel and agents, then panel compile with the reviewed study and input digests and every seat explicit (null for baseline). Compilation changes studyKind and studyType to multi-agent, including when the source draft was a concept study. Review that intent before applying it; duplicate a draft if the original design must remain available.\n\nUse design expand to preview distinct permutations or baseline/each-solo/all-treated batch rows. Review the rows before design batch, then preserve successful publications if a later row fails. The study authorship interfaces share these owners; Python executes panel turns on its supported runner.\n\nOutputs are compiled pinned scenarios and transcripts with declared outcome measurements. More agents do not imply independent observations. State the unit of analysis, interference assumptions, visibility policy and transcript-judging plan.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n",
      "optimization.md": "# Optimize a steering vector\n\nTrain an intervention against a declared objective and evaluate it on separate data.\n\nAsk the researcher to specify the objective, construct, counterfactual/control, model/revision, injection sites, dose convention and train/dev/test split. Optimization data and final evaluation data have different roles.\n\nAuthor the choice-row bundle below, then run `steerlab-server data check optvec --dir <directory> --json`. The prompt emitter has no OptVec-specific kind; use the coworker brief in this guide. Preserve item IDs, option order, declared target labels and pinned split files. Do not infer target labels from option length, topic or a conveniently available answer column.\n\nThe engine's optvec family exposes train, eval, geometry, interpret, family, fracture, gradient, jspace and campaign. Use the exact operation references below and each verb's public help; their closed config validators are the authority. In the app, Data → OptVec starts with Train a vector, Evaluate a vector, and Plan a campaign. Data → Concepts & Vectors also opens the training form. These use the same managed operation owners as the agent client. OptVec learns a vector by optimizing an objective; a steering-strength sweep tests already chosen directions at different strengths. J-space analysis is a separate coordinate analysis, not another name for OptVec training.\n\nTraining produces a vector artifact and optimization record. Evaluate held-out behavior and capability costs; geometric similarity, a training objective improvement and a family plot answer different questions. Report checkpoint selection and the dose actually tested. Never tune a final test split or describe a null-direction comparison as a calibrated statistical test without a declared test design.\n\n## Dataset bundle and author brief\n\nA choice row declares the target explicitly, even though the loader has a default:\n\n```json\n{\"id\":\"target-train-1\",\"prompt\":\"A described situation. Choose A or B.\",\"options\":[\"A\",\"B\"],\"target\":\"B\"}\n```\n\nAuthor `target-train.jsonl`, `target-val.jsonl`, `target-test.jsonl`, `anchor-train.jsonl`, `anchor-val.jsonl`, `anchor-test.jsonl`, `capability-train.jsonl`, `capability-eval.jsonl` and `neutral-fluency.jsonl` (text rows). Keep IDs unique across all files, target A/B balance within 45–55% per choice file, and content/fact patterns disjoint across splits. Tokenizer checks still have to establish single-token options on the pinned model; a single character does not prove that.\n\nPublish `bundle.json` with nonempty `targetIssue`, `shiftDirection`, `caseFamilies` and `anchorIssues`, and a `files` object whose entries each contain `path` and the actual file `sha256`. Include `REPORT.md` with leakage/nuisance checks and unresolved scientific questions. These are dataset records, not changes to an existing study manifest. Use the readiness result's hashes and the selected operation's closed config; never copy placeholder hashes into a training declaration.\n\nGive the coworker the approved target direction, families of situations, invariant anchor judgments and capability domains. Ask for the complete bundle and separate QC report; give another reviewer the inputs and rationale before any training. A predeclared fixed-steps training configuration can omit target validation; report that choice and do not silently reuse the test set for checkpoint selection.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n\n## Shared method authoring and managed execution\n\nUse `science interview <operation> --json` to read the exact form fields used by the app. Answer the purpose, proposed claim, controls and selection questions; supply field values as strings (including integer seeds) and put reviewed extra engine settings in `advanced`. `science draft <operation> --answers <answers.json> --json` resolves file hashes and reports all captured inputs without execution. `science publish <operation> --answers <answers.json> --destination requests/<new-name> --plan-sha256 <reviewed-hash> --json` publishes the machine request and rationale together, refusing changed inputs or an existing destination. Both commands are available under each client executable.\n\nUse the resulting request file with `science input-plan` and `science package`, transfer and stage through the declared site policy, then review and submit the engine plan. The shared form is an authoring aid; the engine still checks its complete scientific config before execution. A successful parser or custody check is not scientific qualification. The workbench API exposes the same local owner at `POST /api/science/workspace/{action}`; it takes `workspaceRoot`, `operation`, and for draft/publish `answersText` (the exact JSON text). Publish also requires `destination` and `planSHA256`. Runner services cannot author the local workspace.\n",
      "readers.md": "# Train and use an activation reader\n\nMeasure an activation-based instrument separately from an intervention.\n\nDecide the construct, template, label interpretation, training split, held-out evaluation split and scoring position with the researcher. A reader's score is not automatically an intervention or a behavioral outcome.\n\nUse the existing reader template registry and reader fit/score interfaces. Request the schema and authoring prompt for the selected template; do not substitute ordinary contrastive-pair files for template-mediated reader inputs. Preserve label alignment, model revision, tokenizer/rendering settings and the exact fitted artifact.\n\nInspect the Readers pane or POST /api/reader/fit and /api/reader/score on a workbench engine. The registry below names supported public paths; these workbench routes are not advertised as batch-runner submissions. Treat training accuracy separately from held-out instrument performance. If importing a reader-derived steering vector, use experiment inspect-artifact and attach-artifact with exact artifact/sidecar/manifest reviews and retain its reader provenance.\n\nOutputs are the fitted reader artifact and scored records. Report the training/evaluation split and applicability to this model and rendering. A successful fit does not establish causal control of the named construct.\n\n## Dataset and handoff\n\nChoose exactly one row shape. `contentPair` compares content under one template:\n\n```json\n{\"id\":\"pair-1\",\"concept\":\"construct\",\"positiveStimulus\":\"First matched text.\",\"negativeStimulus\":\"Second matched text.\",\"topic\":\"shared topic\",\"split\":\"train\",\"templateID\":\"chosen-template\"}\n```\n\n`singleStimulus` compares two template instructions on the same content:\n\n```json\n{\"id\":\"row-1\",\"concept\":\"construct\",\"stimulus\":\"An ambiguous situation.\",\"topic\":\"shared topic\",\"split\":\"train\",\"templateID\":\"chosen-template-pair\"}\n```\n\nEmit `authoring prompt reader-pairs --concept <concept> --positive <definition> --negative <definition> --template-id <template> --shape <contentPair|singleStimulus> --json`. Trailing `split:\"test\"` rows orient the fitted sign in this implementation; reserve an additional independent evaluation set before making a generalization claim. Do not relabel sign-selection data as untouched final evaluation. Templates are real registered inputs, not arbitrary IDs to invent. The fit/score request schema is available in the workbench's `/openapi.json`.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n",
      "sae.md": "# Analyze and import SAE features\n\nPreserve feature identity and the import/normalization convention.\n\nChoose the model, release, layer, width, feature IDs and intended use before searching for persuasive examples. In the app, Data → Concepts & Vectors → Import an SAE feature accepts explicit identifiers or a Neuronpedia feature link. Link lookup uses the installed SAELens directory; it never guesses an unknown mapping or downloads weights. The researcher reviews the selected feature and calibration before import can download weights. Analysis → Compare with Gemma Scope features compares existing vectors with features. Agents use `steerlab-server gemmascope resolve-feature --url <link>`, then `gemmascope import-id`, or the corresponding `/api/gemmascope` operations. The sae family exposes check, pin, family-report and qualification operations.\n\nInputs are release/model metadata, feature identity and any declared analysis corpus. A feature selected from a report and a feature imported directly by ID have different normalization conventions. Preserve the sidecar's gemmascopeConvention: analyzed-vector-norm-match for report-ranked imports, residual-norm-match for direct feature-ID imports. An unstamped legacy artifact requires the documented re-import/qualification repair before evidence use.\n\nUse experiment inspect-artifact and attach-artifact to attach the actual tensor and sidecar with their reviewed hashes. Never relabel a decoder row as an ordinary contrastive extraction or rewrite an old artifact stamp by hand.\n\nOutputs are analysis/qualification records and immutable vector artifacts with feature provenance. Reconstruction, activation examples and steering effects are separate measurements. Report selection criteria, held-out behavior and capability costs; an interpretable feature name is not independent construct validation.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n\n## Shared method authoring and managed execution\n\nUse `science interview <operation> --json` to read the exact form fields used by the app. Answer the purpose, proposed claim, controls and selection questions; supply field values as strings (including integer seeds) and put reviewed extra engine settings in `advanced`. `science draft <operation> --answers <answers.json> --json` resolves file hashes and reports all captured inputs without execution. `science publish <operation> --answers <answers.json> --destination requests/<new-name> --plan-sha256 <reviewed-hash> --json` publishes the machine request and rationale together, refusing changed inputs or an existing destination. Both commands are available under each client executable.\n\nUse the resulting request file with `science input-plan` and `science package`, transfer and stage through the declared site policy, then review and submit the engine plan. The shared form is an authoring aid; the engine still checks its complete scientific config before execution. A successful parser or custody check is not scientific qualification. The workbench API exposes the same local owner at `POST /api/science/workspace/{action}`; it takes `workspaceRoot`, `operation`, and for draft/publish `answersText` (the exact JSON text). Publish also requires `destination` and `planSHA256`. Runner services cannot author the local workspace.\n\nThe offline roster paths are `science sae-check <roster>`, `science sae-show <qualification>`, and `science sae-pin-plan <roster> --experiment <draft>`. Pin with `science sae-pin <roster> --experiment <draft> --plan-sha256 <reviewed-hash>`. Paths are workspace-relative. Both CLIs and the app call the same portable owner. The workbench endpoint uses actions `sae-check`/`sae-show` with `workspaceRoot` and `path`, and `sae-pin-plan`/`sae-pin` also take `experiment`; pin adds `planSHA256`. These are workbench operations, never runner authorship.\n\n## Import a custom decoder or an exported feature\n\nSupply a fitted decoder you already have, or one already-exported feature.\nA coding agent should consult the artifact's documentation for the model, feature\naxis, and hook site, and ask you about missing metadata. The miniature example\nbelow uses a two-dimensional residual space only to illustrate the file format.\n\n```json\n{\n  \"schemaVersion\": 1,\n  \"kind\": \"sae-decoder\",\n  \"modelID\": \"example/model\",\n  \"modelRevision\": null,\n  \"hiddenSize\": 2,\n  \"layerCount\": 4,\n  \"tensorFile\": \"decoder.safetensors\",\n  \"calibrationArtifact\": \"runs/calibration/donor\",\n  \"sae\": {\n    \"layer\": 1,\n    \"feature\": 7,\n    \"decoderKey\": \"W_dec\",\n    \"featureAxis\": \"rows\",\n    \"site\": \"resid_post\",\n    \"label\": \"Candidate behavior\"\n  }\n}\n```\n\nUse actual dimensions and a calibration artifact measured on the same Python\nmodel. `featureAxis` is `rows` or `columns` for a decoder matrix, or `vector` for\none already-exported one-dimensional feature. With `vector`, `feature` records\nits original feature number. The vector is scaled to the measured residual norm;\nthe donor supplies geometry and scale, not a semantic label. Known fit revisions\nmust match; null stays unknown. Source tensors must be finite and nonzero at the\nselected feature. This path applies a residual-post direction; other hook sites\nneed a matching intervention, and full latent SAE manipulation needs more than\none decoder vector.\n\nSafetensors and numeric NPZ work with the lightweight client. Tensor-only PyTorch\ncheckpoints and BF16 require the optional PyTorch reader. Optional `configFile`\nretains original configuration bytes; optional `source` records a repository,\nits exact revision, and/or a discovery URL without claiming a network fetch.\n\nUse `science artifact-plan <description.json> --json`, then\n`science artifact-import <description.json> --plan-sha256 <reviewed-hash> --json`\nthrough either client, with its usual destination workspace option. In the app,\nchoose **Import my own SAE decoder files** in the SAE dialog. The destination\nworkbench must already have the calibration artifact named in the description.\nStage and review copies files, and Import publishes a new vector with retained\nsource bytes. It never trains an SAE, invents data, or proves the feature label.\n",
      "stability.md": "# Diagnose extraction stability\n\nCheck sensitivity to resampling without mistaking it for behavioral validation.\n\nSelect a concept already declared in a study, its supported meanDifference or lat recipe, model/revision, resample count, fraction and seed. LAT additionally has order-shuffle sensitivity because row order enters its arithmetic.\n\nThe stability operation captures the same extraction rows as the engine, then resamples them. It writes a diagnostic outside immutable runs and does not replace the pinned vector. Read stimulusDrift: the diagnostic can report live stimulus bytes that differ from the study's pins. Restore/review those inputs rather than interpreting the result as a reading of the old artifact.\n\nUse `steerlab-server experiment extract-stability <study> <concept> --resamples 32 --fraction 0.8 --seed 1 --json` on the compute host. For a managed remote job, use `runner science-plan` / `runner science-submit` (Python client), `remote science-plan` / `remote science-submit` (Mac), or `POST /api/science/plan` and `/api/science/submit`. Supply operation `stability` with parameters `experiment`, `concept` and optional `resamples`, `fraction`, `seed`, `orderShuffles`, `dtype`, `device`. Submit the exact returned `planSHA256`. Use `science input-plan` and `science package` to review and capture local inputs. Transfer the archive under the declared policy, then `runner science-stage` (Mac `remote science-stage`) returns the isolated execution request. Plan and submit in the same controller session; restart requires a new plan. The child rechecks inputs after queueing, and the job retains the diagnostic path. It does not resume from a checkpoint. CPU resampling still requires a model activation capture first. Mac numerical parity is not claimed; a Mac user can run the Python engine through its captured endpoint.\n\nReport per-layer cosine movement, sign flips and the resampling settings. Stability does not show behavioral efficacy, construct specificity or a safe dose. Follow with held-out validation and a controlled behavioral study; do not invent a universal acceptance threshold.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n\nRemote requests accept the seed as an unsigned integer or decimal string; plans return decimal text to preserve all UInt64 digits across clients.\n\nCompleted diagnostics can travel home through `runner science-fetch` (Mac `remote science-fetch`) or permitted external transfer followed by `science import`. `science custody` and `science verify-custody` re-read retained archives and expanded files offline. A verified receipt proves byte custody, not scientific qualification. Managed removal requires a declared server retention policy, reviewed `cleanup-plan`, fresh local verification and explicit `cleanup-apply --confirm-removal`; only isolated successful diagnostic output copies are eligible. Inputs, export archives, job records and local evidence are retained.\n",
      "style.md": "# Rescore recorded generations\n\nCompute declared style features without rerunning generation.\n\nChoose the taxonomy, source run and interpretation with the researcher. The study must pin the intended taxonomy; the source must satisfy the owner's epoch checks.\n\nUse experiment rescore-style on the Mac or Python engine. There is no dedicated HTTP rescoring route. This is CPU-only post-hoc computation over recorded sampled generations. The source run is immutable: outputs go to a fresh rescore run with reasoning-style.csv and reasoning-style.json.\n\nKeep this explicitly post-hoc when the features were chosen after seeing outputs. A style score is not a new generation, an extraction, a judge verdict or proof of a psychological state. Report taxonomy/source pins, missing outputs and whether the feature definitions were preregistered. Do not bypass an epoch refusal by rewriting the manifest or source metadata.\n\n## Explicit source\n\nOn the Mac: `steerlab-cli experiment rescore-style <study> --run <run> --json`.\nOn the Python engine: `steerlab-server experiment rescore-style <study> --source <run> --json`.\nThese source flags deliberately retain their existing spellings. Read `result.runDirectory` from the Python response; the output contains the new reasoning-style CSV/JSON. Choose and pin the taxonomy before rescoring. Do not describe a post hoc taxonomy choice as preregistered, or use a legacy-epoch override without the researcher's explicit acceptance of that limitation.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n\n## Shared method authoring and managed execution\n\nUse `science interview <operation> --json` to read the exact form fields used by the app. Answer the purpose, proposed claim, controls and selection questions; supply field values as strings (including integer seeds) and put reviewed extra engine settings in `advanced`. `science draft <operation> --answers <answers.json> --json` resolves file hashes and reports all captured inputs without execution. `science publish <operation> --answers <answers.json> --destination requests/<new-name> --plan-sha256 <reviewed-hash> --json` publishes the machine request and rationale together, refusing changed inputs or an existing destination. Both commands are available under each client executable.\n\nUse the resulting request file with `science input-plan` and `science package`, transfer and stage through the declared site policy, then review and submit the engine plan. The shared form is an authoring aid; the engine still checks its complete scientific config before execution. A successful parser or custody check is not scientific qualification. The workbench API exposes the same local owner at `POST /api/science/workspace/{action}`; it takes `workspaceRoot`, `operation`, and for draft/publish `answersText` (the exact JSON text). Publish also requires `destination` and `planSHA256`. Runner services cannot author the local workspace.\n",
      "workflows.json": "{\n  \"schemaVersion\": 1,\n  \"answerSchema\": {\n    \"purpose\": \"Research question in plain language\",\n    \"claim\": \"Proposed claim and its limits\",\n    \"controls\": \"Comparisons and controls\",\n    \"selection\": \"Training/selection/test separation or explanation of why it does not apply\",\n    \"fields\": \"Map of field IDs to text values. Omitted or blank optional fields use the interview default when present; required fields cannot be blank. Integers preserve their values without floating-point conversion.\",\n    \"advanced\": \"Optional original config fields; cannot overwrite form fields\"\n  },\n  \"operations\": [\n    {\n      \"id\": \"optvec-train\",\n      \"title\": \"Train a steering vector\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Teach a vector to favor a chosen answer over an alternative, while preserving other judgments and abilities. Start with your own choice prompts or prompts prepared from study outputs.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to execute\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose the prepared model; this does not acquire weights.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Model commit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"The exact version of the model. Inspect the selected model to fill its commit automatically; an agent can also supply a verified commit. This prevents silently switching model versions.\"\n        },\n        {\n          \"id\": \"layer\",\n          \"label\": \"Injection layer\",\n          \"kind\": \"integer\",\n          \"required\": true,\n          \"help\": \"The transformer layer where the learned vector is added (zero-based). Choose a layer supported by your model and study design; no universal best layer is assumed.\"\n        },\n        {\n          \"id\": \"alphaNormFactor\",\n          \"label\": \"Dose in residual-norm units\",\n          \"kind\": \"number\",\n          \"required\": false,\n          \"help\": \"Steering strength relative to the model’s typical activation size. For example, 0.1 means one tenth of the measured residual norm. This is not a J-space artifact-norm multiple.\",\n          \"default\": \"0.1\"\n        },\n        {\n          \"id\": \"residualNormArtifact\",\n          \"label\": \"Artifact supplying the residual norm\",\n          \"kind\": \"artifact\",\n          \"required\": false,\n          \"help\": \"Choose an inspected artifact with a residual norm table, or explicitly provide alphaAbsolute under advanced settings.\"\n        },\n        {\n          \"id\": \"datasets.targetTrain\",\n          \"label\": \"Target training items\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Examples of the behavior to change. For each prompt, state two answer choices and the answer to encourage. Training increases its log-probability relative to the other choice. Study outputs must first be authored into this choice-row format; they are not consumed directly. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"datasets.targetVal\",\n          \"label\": \"Selection / validation items\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Separate examples of the same behavior, used for checkpoint selection or monitoring. Do not reuse training or final-test rows. A declared fixed-step run can omit this file. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"datasets.anchorTrain\",\n          \"label\": \"Behaviors to preserve\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Judgments you want to leave unchanged. The optimizer penalizes changes to the unsteered model’s answer probabilities on these prompts, rather than teaching the target label as a new answer. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"datasets.anchorVal\",\n          \"label\": \"Anchor validation items\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Separate preservation examples for checking whether the trained vector changes judgments you meant to preserve. Keep them distinct from the preservation training rows. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"datasets.capabilityTrain\",\n          \"label\": \"Capability training controls\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Questions with objectively correct answers, such as basic reasoning or factual tasks. Here target is the correct answer; the optimizer penalizes losing it. Use examples relevant to the abilities your study needs. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"stepsMax\",\n          \"label\": \"Maximum optimization steps\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Upper limit on optimizer updates, not the number of examples. The existing default is a starting setting to review, not a recommended value for every study.\",\n          \"default\": \"500\"\n        },\n        {\n          \"id\": \"seed\",\n          \"label\": \"Random seed\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Record the seed before execution.\",\n          \"default\": \"0\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Training objective improvement is not held-out behavioral validation.\",\n      \"questions\": [\n        \"What behavior should change, and in which direction?\",\n        \"Which judgments and capabilities must remain stable?\",\n        \"Is checkpoint selection based on validation, or are fixed steps predeclared? Keep final test data separate.\"\n      ]\n    },\n    {\n      \"id\": \"optvec-eval\",\n      \"title\": \"Evaluate an optimized intervention\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Measure held-out behavior, capability costs and dose dependence.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to execute\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose the prepared model; this does not acquire weights.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Model commit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"The exact version of the model. Inspect the selected model to fill its commit automatically; an agent can also supply a verified commit. This prevents silently switching model versions.\"\n        },\n        {\n          \"id\": \"vectorArtifact\",\n          \"label\": \"Intervention to test\",\n          \"kind\": \"artifact\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"datasets.targetTest\",\n          \"label\": \"Held-out target test items\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Unseen examples for measuring the desired behavior after training and selection. Keep these out of training and checkpoint selection. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"datasets.anchorTest\",\n          \"label\": \"Held-out anchor items\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Unseen preservation examples for measuring changes to other judgments after training. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"datasets.capabilityEval\",\n          \"label\": \"Held-out capability items\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Unseen questions with correct target answers for checking retained abilities. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"neutralTexts\",\n          \"label\": \"Neutral fluency texts\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Independent passages for checking whether steering harms ordinary language fluency. Use one passage per line, either plain text or a JSON object with a text field. These are not multiple-choice training rows. The example illustrates syntax only; choose passages suitable for your study.\",\n          \"example\": \"{\\\"text\\\": \\\"Describe how to organize a bookshelf.\\\"}\"\n        },\n        {\n          \"id\": \"alphaMultiples\",\n          \"label\": \"Multiples of the trained dose\",\n          \"kind\": \"numbers\",\n          \"required\": true,\n          \"help\": \"\",\n          \"default\": \"0.5, 1, 2\"\n        },\n        {\n          \"id\": \"seed\",\n          \"label\": \"Random seed\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Record the seed before execution.\",\n          \"default\": \"0\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Test results cannot be reused to select the training checkpoint without declaring that selection.\",\n      \"questions\": [\n        \"Which files were kept out of training and checkpoint selection?\",\n        \"Which dose grid and controls were fixed before seeing these results?\"\n      ]\n    },\n    {\n      \"id\": \"optvec-geometry\",\n      \"title\": \"Compare vector geometry\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Describe similarity and multiplicity among declared intervention artifacts.\",\n      \"fields\": [\n        {\n          \"id\": \"artifacts\",\n          \"label\": \"Vector artifacts, one per line\",\n          \"kind\": \"artifacts\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"layer\",\n          \"label\": \"Layer (optional consistency check)\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"The transformer layer where the learned vector is added (zero-based). Choose a layer supported by your model and study design; no universal best layer is assumed.\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Geometric similarity or clustering is not behavioral equivalence or a calibrated statistical test.\",\n      \"questions\": [\n        \"Which independent solutions are being compared?\",\n        \"What would similarity or separation mean for the research question?\"\n      ]\n    },\n    {\n      \"id\": \"optvec-fracture\",\n      \"title\": \"Describe solution basins\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Describe similarity and multiplicity among declared intervention artifacts.\",\n      \"fields\": [\n        {\n          \"id\": \"artifacts\",\n          \"label\": \"Vector artifacts, one per line\",\n          \"kind\": \"artifacts\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"layer\",\n          \"label\": \"Layer (optional consistency check)\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"The transformer layer where the learned vector is added (zero-based). Choose a layer supported by your model and study design; no universal best layer is assumed.\"\n        },\n        {\n          \"id\": \"items\",\n          \"label\": \"Artifact-to-item grouping\",\n          \"kind\": \"documentFile\",\n          \"required\": false,\n          \"help\": \"Choose a JSON map prepared from declared item identities; never infer grouping from filenames.\"\n        },\n        {\n          \"id\": \"gradients\",\n          \"label\": \"Optional gradient tensor file\",\n          \"kind\": \"file\",\n          \"required\": false,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"threshold\",\n          \"label\": \"Clustering cosine threshold\",\n          \"kind\": \"number\",\n          \"required\": false,\n          \"help\": \"\",\n          \"default\": \"0.8\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Geometric similarity or clustering is not behavioral equivalence or a calibrated statistical test.\",\n      \"questions\": [\n        \"Which independent solutions are being compared?\",\n        \"What would similarity or separation mean for the research question?\"\n      ]\n    },\n    {\n      \"id\": \"optvec-interpret\",\n      \"title\": \"Interpret an optimized intervention\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Read logit-lens, probe, optional SAE/J-lens and library measurements.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to execute\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose the prepared model; this does not acquire weights.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Model commit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"The exact version of the model. Inspect the selected model to fill its commit automatically; an agent can also supply a verified commit. This prevents silently switching model versions.\"\n        },\n        {\n          \"id\": \"vectorArtifact\",\n          \"label\": \"Intervention to inspect\",\n          \"kind\": \"artifact\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"probePrompts\",\n          \"label\": \"Held-out probe prompts\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Held-out prompts for inspecting the trained vector’s behavior. Use one prompt per line, either plain text or a JSON object with a text field. These are not multiple-choice training rows. The example illustrates syntax only; choose prompts suitable for your study.\",\n          \"example\": \"{\\\"text\\\": \\\"Describe how to organize a bookshelf.\\\"}\"\n        },\n        {\n          \"id\": \"alphaMultiples\",\n          \"label\": \"Artifact dose multiples\",\n          \"kind\": \"numbers\",\n          \"required\": false,\n          \"help\": \"\",\n          \"default\": \"1\"\n        },\n        {\n          \"id\": \"jlensLensID\",\n          \"label\": \"Optional imported J-lens ID\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"seed\",\n          \"label\": \"Random seed\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Record the seed before execution.\",\n          \"default\": \"0\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Self-explanations and readouts are suggestive measurements, not independent causal evidence. Optional failed stages remain visible.\",\n      \"questions\": [\n        \"Which readouts are relevant to the proposed claim?\",\n        \"Which optional stages and comparison libraries are predeclared?\"\n      ]\n    },\n    {\n      \"id\": \"optvec-family\",\n      \"title\": \"Summarize interpretation readings\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Compare multiple completed interpretation reports.\",\n      \"fields\": [\n        {\n          \"id\": \"interpretRuns\",\n          \"label\": \"Interpretation runs, one per line\",\n          \"kind\": \"files\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"matchNullPercentile\",\n          \"label\": \"Descriptive match percentile\",\n          \"kind\": \"number\",\n          \"required\": false,\n          \"help\": \"\",\n          \"default\": \"95\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"A family summary reports descriptive matches; it does not establish a causal taxonomy.\",\n      \"questions\": [\n        \"Which completed interpretation readings belong in this family?\"\n      ]\n    },\n    {\n      \"id\": \"optvec-gradient\",\n      \"title\": \"Survey per-item gradient directions\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Measure local derivatives and their finite-dose behavior.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to execute\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose the prepared model; this does not acquire weights.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Model commit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"The exact version of the model. Inspect the selected model to fill its commit automatically; an agent can also supply a verified commit. This prevents silently switching model versions.\"\n        },\n        {\n          \"id\": \"layer\",\n          \"label\": \"Injection layer\",\n          \"kind\": \"integer\",\n          \"required\": true,\n          \"help\": \"The transformer layer where the learned vector is added (zero-based). Choose a layer supported by your model and study design; no universal best layer is assumed.\"\n        },\n        {\n          \"id\": \"datasets.targetTrain\",\n          \"label\": \"Survey items\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Examples of the behavior to change. For each prompt, state two answer choices and the answer to encourage. Training increases its log-probability relative to the other choice. Study outputs must first be authored into this choice-row format; they are not consumed directly. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"alphaNormFactor\",\n          \"label\": \"Dose in residual-norm units\",\n          \"kind\": \"number\",\n          \"required\": false,\n          \"help\": \"Steering strength relative to the model’s typical activation size. For example, 0.1 means one tenth of the measured residual norm. This is not a J-space artifact-norm multiple.\",\n          \"default\": \"0.1\"\n        },\n        {\n          \"id\": \"residualNormArtifact\",\n          \"label\": \"Artifact supplying the residual norm\",\n          \"kind\": \"artifact\",\n          \"required\": false,\n          \"help\": \"Choose an inspected artifact with a residual norm table, or explicitly provide alphaAbsolute under advanced settings.\"\n        },\n        {\n          \"id\": \"doseLadder\",\n          \"label\": \"Positive dose fractions\",\n          \"kind\": \"numbers\",\n          \"required\": true,\n          \"help\": \"\",\n          \"default\": \"0.25, 0.5, 1\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"An alpha-to-zero derivative need not describe effects at a usable finite dose.\",\n      \"questions\": [\n        \"Which item population is being surveyed?\",\n        \"What dose ladder tests the local approximation?\"\n      ]\n    },\n    {\n      \"id\": \"optvec-gradient-mint\",\n      \"title\": \"Publish one surveyed direction\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Create a new vector artifact from an explicitly selected survey item.\",\n      \"fields\": [\n        {\n          \"id\": \"surveyRun\",\n          \"label\": \"Completed gradient survey run\",\n          \"kind\": \"file\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"itemID\",\n          \"label\": \"Explicit item ID\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Selecting an item after inspection is a selection decision; record the rationale before downstream testing.\",\n      \"questions\": [\n        \"Why was this item selected, and where will its direction be tested independently?\"\n      ]\n    },\n    {\n      \"id\": \"jspace\",\n      \"title\": \"Analyze an intervention in J-space\",\n      \"method\": \"jspace\",\n      \"purpose\": \"Inspect downstream residual changes through an imported J-lens. This does not optimize or train a vector.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to execute\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose the prepared model; this does not acquire weights.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Model commit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Inspect the immutable 40-character model commit. Never type a guessed pin.\"\n        },\n        {\n          \"id\": \"vectorArtifacts\",\n          \"label\": \"Intervention artifacts, one per line\",\n          \"kind\": \"artifacts\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"lensID\",\n          \"label\": \"Imported J-lens ID\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"probeItems\",\n          \"label\": \"Pinned choice-row probes\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Choose a workspace-relative file. Its actual SHA-256 is read during review.\"\n        },\n        {\n          \"id\": \"observationLayers\",\n          \"label\": \"Observation layers (comma-separated)\",\n          \"kind\": \"integers\",\n          \"required\": false,\n          \"help\": \"Only fitted source layers at or above injection; leave blank for the engine’s eligible ladder.\"\n        },\n        {\n          \"id\": \"alphaMultiple\",\n          \"label\": \"Multiple of the artifact’s own norm\",\n          \"kind\": \"number\",\n          \"required\": true,\n          \"help\": \"This is not ordinary residual-norm alpha.\",\n          \"default\": \"1\"\n        },\n        {\n          \"id\": \"nullSeed\",\n          \"label\": \"Matched-direction null seed\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"\",\n          \"default\": \"20260810\"\n        },\n        {\n          \"id\": \"nullDraws\",\n          \"label\": \"Matched-direction comparisons\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"\",\n          \"default\": \"1\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Arithmetic fidelity, predictive readout and behavioral/causal evidence are different. This operation supplies no behavioral causal test; null draws are comparators, not calibrated p-values. The current batch implementation requires OptVec artifact metadata for layer and dose; other artifact types are not yet accepted.\",\n      \"questions\": [\n        \"Which intervention, lens and probe distribution answer the question?\",\n        \"What observation layers and dose are justified?\",\n        \"What separate controlled behavioral study will test any causal interpretation?\"\n      ]\n    },\n    {\n      \"id\": \"rescore-style\",\n      \"title\": \"Rescore existing generations for style\",\n      \"method\": \"style\",\n      \"purpose\": \"Apply a pinned reasoning-style taxonomy to a completed generation run.\",\n      \"fields\": [\n        {\n          \"id\": \"experiment\",\n          \"label\": \"Study name\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"sourceRun\",\n          \"label\": \"Completed generation run\",\n          \"kind\": \"file\",\n          \"required\": true,\n          \"help\": \"\"\n        }\n      ],\n      \"claimBoundary\": \"Rescoring changes measurement, not the original generations. The source epoch gate still applies.\",\n      \"questions\": [\n        \"Which taxonomy is pinned, and why does it measure the intended construct?\",\n        \"Is this a planned measurement or a post-hoc analysis?\"\n      ]\n    },\n    {\n      \"id\": \"sae-family-report\",\n      \"title\": \"Compare intervention families\",\n      \"method\": \"sae\",\n      \"purpose\": \"Produce a descriptive cross-family report from artifacts and behavioral evidence.\",\n      \"fields\": [\n        {\n          \"id\": \"artifacts\",\n          \"label\": \"Family entries\",\n          \"kind\": \"documentFile\",\n          \"required\": true,\n          \"help\": \"Choose the reviewed JSON array of vector references and/or labeled behavior-only entries.\"\n        },\n        {\n          \"id\": \"discoverPromotions\",\n          \"label\": \"Inspect promotion provenance\",\n          \"kind\": \"boolean\",\n          \"required\": false,\n          \"help\": \"\",\n          \"default\": \"true\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Behavioral deltas are copied from their declared evidence; this report adds no inferential statistics.\",\n      \"questions\": [\n        \"Which family members and behavioral sources are comparable?\"\n      ]\n    },\n    {\n      \"id\": \"sae-qualification-record\",\n      \"title\": \"Record SAE feature qualification\",\n      \"method\": \"sae\",\n      \"purpose\": \"Bind declared qualification evidence to the exact imported feature.\",\n      \"fields\": [\n        {\n          \"id\": \"artifact\",\n          \"label\": \"Imported feature artifact\",\n          \"kind\": \"artifact\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"inputs\",\n          \"label\": \"Reviewed qualification inputs\",\n          \"kind\": \"documentFile\",\n          \"required\": true,\n          \"help\": \"Use the shipped SAE qualification template and an independent reviewer; select the completed inputs file.\"\n        }\n      ],\n      \"claimBoundary\": \"A qualification declaration must be supported by the feature identity, dose coverage and evidence; it does not seat an agent or prove a broad construct.\",\n      \"questions\": [\n        \"Who reviewed the feature identity, construct probes, sign/dose coverage and final rationale?\"\n      ]\n    },\n    {\n      \"id\": \"optvec-campaign\",\n      \"title\": \"Prepare an optimization campaign\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Materialize a reviewed grid of training cells; scheduler top-up is a separate explicit action.\",\n      \"fields\": [\n        {\n          \"id\": \"name\",\n          \"label\": \"Campaign name\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"baseConfig\",\n          \"label\": \"Reviewed base training configuration\",\n          \"kind\": \"documentFile\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"grid\",\n          \"label\": \"Reviewed grid of layers, seeds and conditions\",\n          \"kind\": \"documentFile\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"slurm\",\n          \"label\": \"Reviewed scheduler settings\",\n          \"kind\": \"documentFile\",\n          \"required\": true,\n          \"help\": \"\"\n        }\n      ],\n      \"claimBoundary\": \"A materialized campaign is not completed training. Cell outcomes and uncertain submissions remain individually visible.\",\n      \"questions\": [\n        \"Which axes and stopping/attempt budgets were chosen before results?\",\n        \"Which resource and queue policies apply to every cell?\"\n      ]\n    },\n    {\n      \"id\": \"jlens-fit\",\n      \"title\": \"Fit a new J-lens\",\n      \"method\": \"jlens\",\n      \"purpose\": \"Build a model-specific instrument that maps intermediate residual activations into the final-layer basis. Choose your text, measure a pilot, and retain the fitting recipe.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to fit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose a prepared Hugging Face checkpoint. Fitting does not download model weights or change them.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Exact model version\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Inspect the model to pin its 40-character commit. The resulting lens belongs to this checkpoint.\"\n        },\n        {\n          \"id\": \"corpus\",\n          \"label\": \"Text corpus for fitting\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Use varied text representative of where you intend to read the model. This is not positive/negative concept data. Supply UTF-8 JSONL with one unique id and text per row. Choose existing text, or ask for an authoring prompt; no data is generated automatically.\",\n          \"example\": \"{\\\"id\\\":\\\"sample-1\\\",\\\"text\\\":\\\"Replace this sentence with a sufficiently long passage from your chosen, documented corpus.\\\"}\"\n        },\n        {\n          \"id\": \"corpusReceipt\",\n          \"label\": \"Corpus preparation receipt\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Optional preparation.json saved beside a prepared corpus. It records source revisions, selected records, sampling, and token review, and travels with the fitting inputs. Existing manually authored corpora do not need a receipt.\"\n        },\n        {\n          \"id\": \"maxPrompts\",\n          \"label\": \"Maximum corpus rows (start with a small pilot)\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"default\": \"4\",\n          \"help\": \"Fits the first N rows in file order. Four rows provide a timing pilot, not a well-established lens. Increase after reviewing time, memory, and corpus coverage. Short rows are counted in this limit and recorded as skipped. The request review shows matrix memory and backward-pass estimates when the pinned model configuration is cached locally; otherwise it explains how to obtain an engine estimate.\"\n        },\n        {\n          \"id\": \"sourceLayers\",\n          \"label\": \"Source layers\",\n          \"kind\": \"integers\",\n          \"required\": false,\n          \"help\": \"Blank fits all layers before the final block. Select fewer layers for a cheaper or targeted instrument; token-vector creation needs full coverage. Layer numbers start at zero.\"\n        },\n        {\n          \"id\": \"maxSeqLen\",\n          \"label\": \"Maximum tokens per passage\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"default\": \"128\",\n          \"help\": \"Longer text is truncated to this many tokens. Raw text uses the tokenizer’s native special tokens; no chat template is added.\"\n        },\n        {\n          \"id\": \"skipFirst\",\n          \"label\": \"Leading token positions to omit\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"default\": \"16\",\n          \"help\": \"The reference estimator omits early positions and the final token. A passage must have more than this value plus one token after tokenization.\"\n        },\n        {\n          \"id\": \"dimBatch\",\n          \"label\": \"Jacobian dimensions per backward pass\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"default\": \"1\",\n          \"help\": \"A memory/performance control. The model repeats the passage this many times per pass. Larger values need more activation memory; start with 1 on a large model. For example, width 5,376 needs 5,376 backward passes per row at batch 1, or 672 at batch 8. Batching uses more activation memory; it does not promise proportional acceleration.\"\n        },\n        {\n          \"id\": \"checkpointEvery\",\n          \"label\": \"Checkpoint every N considered rows\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"default\": \"4\",\n          \"help\": \"A checkpoint may contain several gigabytes. Smaller intervals preserve more progress but increase disk traffic. Active scratch keeps the latest complete snapshot; completed runs retain their final snapshot.\"\n        },\n        {\n          \"id\": \"dtype\",\n          \"label\": \"Model precision\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"default\": \"bfloat16\",\n          \"help\": \"Choose bfloat16, float32, or float16. The fitted Jacobian accumulates and saves in float32. Quantized fitting is not implemented.\"\n        },\n        {\n          \"id\": \"device\",\n          \"label\": \"Python execution device\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"default\": \"cuda\",\n          \"help\": \"cuda (or cuda:0) on the cluster, mps on a compatible Mac, or cpu for small numerical tests. The pilot must verify backward support on this architecture.\"\n        },\n        {\n          \"id\": \"tier\",\n          \"label\": \"Intended lens use\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"default\": \"testing\",\n          \"help\": \"testing for rehearsal, or evidence for intended study use. This declaration does not qualify the lens or validate a behavioral interpretation.\"\n        },\n        {\n          \"id\": \"checkpoint\",\n          \"label\": \"Continue from a completed checkpoint (optional)\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Choose state.json beside sums.safetensors after the original job has stopped. Both files travel with the request and are read and verified again at execution; multi-gigabyte files can take several minutes. Continuation creates a new run. Numerical settings and dependency versions must match; documentation-only driver changes do not prevent continuation under the same fitting contract.\"\n        },\n        {\n          \"id\": \"compileModel\",\n          \"label\": \"Compile model blocks\",\n          \"kind\": \"boolean\",\n          \"required\": false,\n          \"default\": \"false\",\n          \"help\": \"Optional speed experiment. Compare gradients and fitted lenses against the uncompiled baseline before using it for a longer run; first-call compilation counts in pilot time.\"\n        },\n        {\n          \"id\": \"kernelPolicy\",\n          \"label\": \"Attention kernel selection\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"default\": \"current\",\n          \"help\": \"current uses this prepared environment; torch explicitly selects inspectable Torch fallback functions. No packages are installed. Compare the two in a small benchmark before changing a continuation runtime.\"\n        },\n        {\n          \"id\": \"stopping\",\n          \"label\": \"Optional stopping rule document\",\n          \"kind\": \"documentFile\",\n          \"required\": false,\n          \"help\": \"JSON with threshold, window, and minPrompts. Stops after N consecutive available fitted-row changes below the threshold, after the minimum. Leave blank for a fixed row cap; sharded rounds remain fixed-budget.\",\n          \"example\": \"{\\\"threshold\\\":0.002,\\\"window\\\":10,\\\"minPrompts\\\":100}\"\n        },\n        {\n          \"id\": \"rowIndices\",\n          \"label\": \"Advanced: explicit global row indices\",\n          \"kind\": \"integers\",\n          \"required\": false,\n          \"help\": \"Usually generated by the round planner. Rows remain tied to the original corpus, allowing overlap checks at merge.\"\n        },\n        {\n          \"id\": \"benchmarkReport\",\n          \"label\": \"Optional measured pilot report\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Choose benchmark-report.json from a matching model, corpus, and fitting configuration to display measured rows per hour and a cautious time extrapolation. This is not a walltime guarantee.\"\n        }\n      ],\n      \"claimBoundary\": \"An averaged Jacobian is an instrument fitted to this corpus and runtime. Stable fitting statistics are not evidence of semantic validity or causal steering effects.\",\n      \"questions\": [\n        \"What text population should the lens represent?\",\n        \"How will you assess readouts on held-out text after fitting?\"\n      ]\n    },\n    {\n      \"id\": \"jlens-fit-benchmark\",\n      \"title\": \"Compare fitting speed and numerical agreement\",\n      \"method\": \"jlens\",\n      \"purpose\": \"Measure dimension batches, optional compilation, and prepared attention kernels on the same small text sample.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to fit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose a prepared Hugging Face checkpoint. Fitting does not download model weights or change them.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Exact model version\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Inspect the model to pin its 40-character commit. The resulting lens belongs to this checkpoint.\"\n        },\n        {\n          \"id\": \"fittingRequest\",\n          \"label\": \"Published pilot fitting request\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Choose request.json from a fresh J-lens pilot with at most eight rows. Its corpus and preparation receipt travel with this benchmark.\"\n        },\n        {\n          \"id\": \"dimBatches\",\n          \"label\": \"Dimension batches to compare\",\n          \"kind\": \"integers\",\n          \"required\": false,\n          \"default\": \"1, 8, 16\",\n          \"help\": \"Start with 1 as the reference. Each combination is a fresh worker; larger batches need more device memory.\"\n        },\n        {\n          \"id\": \"kernelPolicies\",\n          \"label\": \"Kernel comparisons\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"default\": \"current\",\n          \"help\": \"current benchmarks the prepared environment; torch uses the inspectable fallback; torch,current compares both. Installing kernels is a separate reviewed environment change.\"\n        },\n        {\n          \"id\": \"compareCompiled\",\n          \"label\": \"Also compare compiled blocks\",\n          \"kind\": \"boolean\",\n          \"required\": false,\n          \"default\": \"false\",\n          \"help\": \"Doubles the number of cases. Includes first-call compilation in timing.\"\n        },\n        {\n          \"id\": \"rtol\",\n          \"label\": \"Relative numerical tolerance\",\n          \"kind\": \"number\",\n          \"required\": false,\n          \"default\": \"0.0001\",\n          \"help\": \"Elementwise tolerance for per-prompt Jacobians and averaged lenses. Review the reported maximum and relative errors as well.\"\n        },\n        {\n          \"id\": \"atol\",\n          \"label\": \"Absolute numerical tolerance\",\n          \"kind\": \"number\",\n          \"required\": false,\n          \"default\": \"0.0001\",\n          \"help\": \"Absolute allowance near zero. This default is a comparison setting, not a claim of scientific adequacy.\"\n        }\n      ],\n      \"claimBoundary\": \"Speed is conditional on these rows and this runtime. Agreement is measured with the displayed tolerances, not a universal scientific guarantee.\",\n      \"questions\": [\n        \"Which small corpus should represent the later fitting workload?\",\n        \"Which numerical differences are acceptable for the intended analysis?\"\n      ]\n    },\n    {\n      \"id\": \"jlens-fit-round\",\n      \"title\": \"Plan a fixed-budget fitting round\",\n      \"method\": \"jlens\",\n      \"purpose\": \"Divide one global row budget into disjoint fitting requests, then review and top up the queue. Materialization starts no GPU work.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to fit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose a prepared Hugging Face checkpoint. Fitting does not download model weights or change them.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Exact model version\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Inspect the model to pin its 40-character commit. The resulting lens belongs to this checkpoint.\"\n        },\n        {\n          \"id\": \"fittingRequest\",\n          \"label\": \"Published fixed-budget fitting request\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Choose a fresh request.json. Its maximum rows become the global round budget, not a per-shard budget.\"\n        },\n        {\n          \"id\": \"shards\",\n          \"label\": \"Number of disjoint shards\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Each shard retains its own lens and checkpoint, can be continued independently, and uses the same numerical settings.\",\n          \"default\": \"4\"\n        },\n        {\n          \"id\": \"maxConcurrent\",\n          \"label\": \"Maximum concurrent scientific jobs\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Set within the site’s policy. Queue top-ups count active scientific jobs on this controller and require an explicit review.\",\n          \"default\": \"1\"\n        },\n        {\n          \"id\": \"startRow\",\n          \"label\": \"First global corpus row\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Zero-based. Later rounds can select a disjoint range of the same pinned corpus.\",\n          \"default\": \"0\"\n        },\n        {\n          \"id\": \"layout\",\n          \"label\": \"Partition layout\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"interleaved distributes successive rows across shards; contiguous gives each shard a consecutive block.\",\n          \"default\": \"interleaved\"\n        }\n      ],\n      \"claimBoundary\": \"Coverage and readout stability must be interpreted for the selected corpus and runtime. Outputs do not establish behavioral validity.\",\n      \"questions\": [\n        \"Which corpus range and resource budget answer the research question?\",\n        \"Which missing coverage or readout differences would change the conclusion?\"\n      ]\n    },\n    {\n      \"id\": \"jlens-fit-merge\",\n      \"title\": \"Merge completed fitting shards\",\n      \"method\": \"jlens\",\n      \"purpose\": \"Merge raw float32 sums in deterministic global-row order, weighted by fitted rows, with overlap detection and recorded source lineage.\",\n      \"fields\": [\n        {\n          \"id\": \"fits\",\n          \"label\": \"Completed fitting runs\",\n          \"kind\": \"files\",\n          \"required\": true,\n          \"help\": \"One workspace-relative run directory per line. Include only the latest completed continuation of each shard; overlapping contributions are rejected.\"\n        },\n        {\n          \"id\": \"allowPartial\",\n          \"label\": \"Allow and label incomplete coverage\",\n          \"kind\": \"boolean\",\n          \"required\": false,\n          \"help\": \"A partial merge records exactly which planned rows are missing. It does not silently pretend all shards finished.\",\n          \"default\": \"true\"\n        },\n        {\n          \"id\": \"tier\",\n          \"label\": \"Intended use\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"testing or evidence. Qualification and held-out assessment remain separate.\",\n          \"default\": \"testing\"\n        }\n      ],\n      \"claimBoundary\": \"Coverage and readout stability must be interpreted for the selected corpus and runtime. Outputs do not establish behavioral validity.\",\n      \"questions\": [\n        \"Which corpus range and resource budget answer the research question?\",\n        \"Which missing coverage or readout differences would change the conclusion?\"\n      ]\n    },\n    {\n      \"id\": \"jlens-fit-assess\",\n      \"title\": \"Assess successive lenses on held-out text\",\n      \"method\": \"jlens\",\n      \"purpose\": \"Measure agreement between two lenses and with the model’s actual final residual on declared held-out token positions.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to fit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose a prepared Hugging Face checkpoint. Fitting does not download model weights or change them.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Exact model version\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Inspect the model to pin its 40-character commit. The resulting lens belongs to this checkpoint.\"\n        },\n        {\n          \"id\": \"corpus\",\n          \"label\": \"Held-out text corpus\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Unique id and text per JSONL row. Choose text not used for fitting or method selection; a different file hash alone does not prove independence.\"\n        },\n        {\n          \"id\": \"referenceLensID\",\n          \"label\": \"Reference registered lens\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose the earlier fit or comparison instrument from the lens library.\"\n        },\n        {\n          \"id\": \"candidateLensID\",\n          \"label\": \"Candidate registered lens\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose the later fit or merged round from the same model and known model revision.\"\n        },\n        {\n          \"id\": \"maxPrompts\",\n          \"label\": \"Maximum passages to assess\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Uses the first N rows in this declared assessment corpus.\",\n          \"default\": \"16\"\n        },\n        {\n          \"id\": \"maxSeqLen\",\n          \"label\": \"Maximum tokens per passage\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Raw text, with the prepared tokenizer’s native special tokens.\",\n          \"default\": \"128\"\n        },\n        {\n          \"id\": \"skipFirst\",\n          \"label\": \"Leading positions to omit\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Early positions and the final token are excluded.\",\n          \"default\": \"16\"\n        },\n        {\n          \"id\": \"maxPositionsPerRow\",\n          \"label\": \"Maximum assessed positions per passage\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Uses the first eligible positions and records them. Vocabulary logits are processed in small chunks.\",\n          \"default\": \"64\"\n        },\n        {\n          \"id\": \"topK\",\n          \"label\": \"Top tokens to compare\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Reports top-k set overlap and Jensen–Shannon divergence, averaged equally over the recorded token positions.\",\n          \"default\": \"10\"\n        },\n        {\n          \"id\": \"dtype\",\n          \"label\": \"Model precision\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"Use the prepared, unquantized runtime appropriate to the intended readout.\",\n          \"default\": \"bfloat16\"\n        },\n        {\n          \"id\": \"device\",\n          \"label\": \"Execution device\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"cuda, mps, or cpu; this assessment does not download weights.\",\n          \"default\": \"cuda\"\n        }\n      ],\n      \"claimBoundary\": \"Coverage and readout stability must be interpreted for the selected corpus and runtime. Outputs do not establish behavioral validity.\",\n      \"questions\": [\n        \"Which corpus range and resource budget answer the research question?\",\n        \"Which missing coverage or readout differences would change the conclusion?\"\n      ]\n    }\n  ]\n}\n"
    }
